import { officeKnowledge } from "./office-knowledge.ts";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash, timingSafeEqual } from "node:crypto";
import { execFileSync, spawnSync } from "node:child_process";

type Phase = "product" | "development";
export type OfficePolicy = {
  taskId: string;
  projectId: string;
  projectPath: string;
  source: string;
  phase: Phase;
  digest: string;
  head: string;
  state: string;
  expiresAt: number;
};
let database: any;
// This short-lived capability exists only in the current server process. It
// admits one exact approved task without opening either global execution flag.
let developmentTaskGrant: { taskId: string; digest: string; expiresAt: number } | null = null;
const TTL = 10 * 60_000;
export const officePolicyEnabled = () => process.env.AI_OFFICE_POLICY_ENABLED === "true";
function fail(code: string, status = 403): never {
  throw Object.assign(new Error(code), { code, status });
}
function db(): any {
  if (!database) fail("office_policy_unconfigured", 503);
  return database;
}
function id(value: unknown): string {
  if (typeof value !== "string" || !/^[a-zA-Z0-9-]{1,64}$/.test(value)) fail("office_invalid_task_id", 400);
  return value;
}
const inside = (candidate: string, root: string) => candidate === root || candidate.startsWith(root + path.sep);
function real(value: string): string {
  try {
    return fs.realpathSync(value);
  } catch {
    return fail("office_path_missing");
  }
}
function denyProjectConfiguration(directory: string): void {
  try {
    fs.lstatSync(path.join(directory, ".codex"));
  } catch (error: any) {
    if (error.code === "ENOENT") return;
    fail("office_project_config_unreadable");
  }
  fail("office_project_config_blocked");
}
function git(source: string, ...args: string[]): string {
  try {
    return execFileSync("git", args, {
      cwd: source,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      timeout: 5000,
    }).trim();
  } catch {
    return fail("office_git_validation_failed");
  }
}
function digest(value: unknown): string {
  return createHash("sha256").update(JSON.stringify(value)).digest("hex");
}
function same(a: unknown, b: unknown): boolean {
  return (
    typeof a === "string" &&
    typeof b === "string" &&
    Buffer.byteLength(a) === Buffer.byteLength(b) &&
    timingSafeEqual(Buffer.from(a), Buffer.from(b))
  );
}
function transaction<T>(fn: () => T): T {
  db().exec("BEGIN IMMEDIATE");
  try {
    const result = fn();
    db().exec("COMMIT");
    return result;
  } catch (e) {
    db().exec("ROLLBACK");
    throw e;
  }
}
export function configureOfficePolicy(input: any): void {
  database = input;
  developmentTaskGrant = null;
  input.exec(`CREATE TABLE IF NOT EXISTS office_task_permissions (
    task_id TEXT PRIMARY KEY, phase TEXT NOT NULL, digest TEXT NOT NULL, payload TEXT NOT NULL,
    state TEXT NOT NULL, expires_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)`);
}
function officeRunner(): { bundle: string; binary: string; sha256: string } {
  const configured = process.env.AI_OFFICE_CODEX_BUNDLE_DIR;
  const expected = process.env.AI_OFFICE_CODEX_SHA256;
  if (!configured || !expected || !/^[a-f0-9]{64}$/.test(expected)) fail("office_runner_not_configured", 503);
  const allowed = real(process.env.AI_OFFICE_PROVIDER_BIN_ROOT || "/workspace/ai-office/provider");
  const bundle = real(configured),
    binary = real(path.join(bundle, "bin", "codex"));
  if (bundle === allowed || !inside(bundle, allowed) || !inside(binary, bundle)) fail("office_runner_outside_root");
  if (!fs.statSync(binary).isFile() || !(fs.statSync(binary).mode & 0o111)) fail("office_runner_not_executable");
  const actual = createHash("sha256").update(fs.readFileSync(binary)).digest("hex");
  if (!same(expected, actual)) fail("office_runner_hash_mismatch");
  return { bundle, binary, sha256: actual };
}
function modelConfigurationDigest(): string | null {
  if (!db().prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='settings'").get()) return null;
  const row = db().prepare("SELECT value FROM settings WHERE key='providerModelConfig'").get();
  return digest(row?.value ?? null);
}
function validateChatGptAuth(source?: string): string {
  const home = providerHome(source);
  let auth: any;
  try {
    auth = JSON.parse(fs.readFileSync(path.join(home, ".codex", "auth.json"), "utf8"));
  } catch {
    fail("office_chatgpt_oauth_required", 503);
  }
  if (
    auth?.auth_mode !== "chatgpt" ||
    auth.OPENAI_API_KEY != null ||
    typeof auth.tokens?.access_token !== "string" ||
    !auth.tokens.access_token.trim() ||
    typeof auth.tokens?.refresh_token !== "string" ||
    !auth.tokens.refresh_token.trim()
  )
    fail("office_chatgpt_oauth_required", 503);
  return home;
}
function probeOfficeSandbox(): void {
  const probe = spawnSync("bwrap", ["--ro-bind", "/", "/", "--unshare-net", "/bin/true"], {
    stdio: "ignore",
    timeout: 5000,
  });
  if (probe.error || probe.status !== 0) fail("office_os_sandbox_unavailable", 503);
}
export function diagnoseOfficeProvider(): { runnerConfigured: boolean; authReady: boolean; reasonCodes: string[] } {
  const result = { runnerConfigured: false, authReady: false, reasonCodes: [] as string[] };
  try {
    officeRunner();
    result.runnerConfigured = true;
  } catch (e: any) {
    result.reasonCodes.push(e.code || "office_runner_unavailable");
  }
  try {
    validateChatGptAuth();
    result.authReady = true;
  } catch (e: any) {
    result.reasonCodes.push(e.code || "office_auth_unavailable");
  }
  return result;
}
export function checkOfficeProviderSandbox(): ReturnType<typeof diagnoseOfficeProvider> & {
  sandboxAvailable: boolean;
} {
  if (!officePolicyEnabled()) fail("office_policy_disabled", 503);
  const result = { ...diagnoseOfficeProvider(), sandboxAvailable: false };
  try {
    probeOfficeSandbox();
    result.sandboxAvailable = true;
  } catch (e: any) {
    result.reasonCodes.push(e.code || "office_os_sandbox_unavailable");
  }
  return result;
}
export function unlockOfficeProductWorkers(confirmation: unknown): { workersEnabled: true; developmentEnabled: false } {
  if (!officePolicyEnabled()) fail("office_policy_disabled", 503);
  if (confirmation !== true) fail("office_confirmation_required", 400);
  if (process.env.AI_OFFICE_DEVELOPMENT_ENABLED === "true") fail("office_development_must_remain_locked");
  if (currentDevelopmentGrant()) fail("office_scoped_development_pending", 409);
  officeRunner();
  validateChatGptAuth();
  probeOfficeSandbox();
  process.env.AI_OFFICE_WORKERS_ENABLED = "true";
  return { workersEnabled: true, developmentEnabled: false };
}
export function lockOfficeWorkers(): { workersEnabled: false; developmentEnabled: boolean } {
  if (!officePolicyEnabled()) fail("office_policy_disabled", 503);
  process.env.AI_OFFICE_WORKERS_ENABLED = "false";
  developmentTaskGrant = null;
  return { workersEnabled: false, developmentEnabled: process.env.AI_OFFICE_DEVELOPMENT_ENABLED === "true" };
}
function currentDevelopmentGrant(): typeof developmentTaskGrant {
  if (developmentTaskGrant && developmentTaskGrant.expiresAt <= Date.now()) developmentTaskGrant = null;
  return developmentTaskGrant;
}
export function unlockOfficeDevelopmentTask(taskId: string, expectedDigest: string, confirmation: unknown) {
  if (!officePolicyEnabled()) fail("office_policy_disabled", 503);
  if (confirmation !== true) fail("office_confirmation_required", 400);
  if (process.env.AI_OFFICE_WORKERS_ENABLED === "true" || process.env.AI_OFFICE_DEVELOPMENT_ENABLED === "true")
    fail("office_global_workers_must_remain_locked", 409);
  if (currentDevelopmentGrant()) fail("office_scoped_development_pending", 409);
  if (
    db().prepare("SELECT 1 FROM office_task_permissions WHERE state='running' LIMIT 1").get() ||
    db().prepare("SELECT 1 FROM tasks WHERE status='in_progress' LIMIT 1").get()
  )
    fail("office_wait_for_running_task", 409);
  const policy = inspect(taskId, ["approved"]);
  if (policy.phase !== "development") fail("office_development_approval_required", 409);
  if (!same(expectedDigest, policy.digest)) fail("office_digest_mismatch", 409);
  officeRunner();
  validateChatGptAuth();
  probeOfficeSandbox();
  // Validation above may take time: admission never extends the approval TTL.
  const finalPolicy = inspect(taskId, ["approved"]);
  if (!same(finalPolicy.digest, expectedDigest)) fail("office_digest_mismatch", 409);
  developmentTaskGrant = { taskId, digest: finalPolicy.digest, expiresAt: finalPolicy.expiresAt };
  return {
    taskId,
    phase: "development" as const,
    scoped: true,
    workersEnabled: false,
    developmentEnabled: false,
    expiresAt: finalPolicy.expiresAt,
  };
}
function current(taskId: string, phase: Phase): Omit<OfficePolicy, "state" | "expiresAt"> & { payload: string } {
  id(taskId);
  if (phase !== "product" && phase !== "development") fail("office_invalid_phase", 400);
  const task = db().prepare("SELECT * FROM tasks WHERE id = ?").get(taskId);
  if (!task?.project_id) fail("office_task_project_required");
  const project = db().prepare("SELECT * FROM projects WHERE id = ?").get(task.project_id);
  if (!project?.project_path) fail("office_project_missing");
  const root = real(process.env.AI_OFFICE_PROJECTS_ROOT || "/workspace/ai-office/projects");
  const projectPath = real(project.project_path);
  if (projectPath === root || !inside(projectPath, root)) fail("office_project_outside_root");
  const source = real(path.join(projectPath, "source"));
  if (source === projectPath || !inside(source, projectPath)) fail("office_source_outside_project");
  denyProjectConfiguration(source);
  if (git(source, "rev-parse", "--show-toplevel") !== source) fail("office_source_not_repository_root");
  const gitDir = real(git(source, "rev-parse", "--absolute-git-dir"));
  if (!inside(gitDir, source) || gitDir === source) fail("office_external_gitdir");
  if (git(source, "status", "--porcelain", "--untracked-files=no")) fail("office_source_dirty");
  const head = git(source, "rev-parse", "HEAD");
  if (task.project_path && ![projectPath, source].includes(real(task.project_path))) fail("office_task_path_mismatch");
  if ((task.workflow_pack_key || "development") !== "development") fail("office_workflow_pack_blocked");
  const handoff = real(path.join(projectPath, "HANDOFF.md"));
  if (!inside(handoff, projectPath) || !fs.statSync(handoff).isFile() || fs.statSync(handoff).size > 65536)
    fail("office_invalid_handoff");
  const content = fs.readFileSync(handoff, "utf8");
  if (phase === "development" && !content.trim()) fail("office_handoff_required");
  const agent = task.assigned_agent_id
    ? db().prepare("SELECT * FROM agents WHERE id = ?").get(task.assigned_agent_id)
    : null;
  if (!agent) fail("office_task_agent_required");
  const fields = [
    "id",
    "title",
    "description",
    "task_type",
    "assigned_agent_id",
    "project_id",
    "project_path",
    "department_id",
    "workflow_pack_key",
    "base_branch",
  ];
  const snapshot = {
    phase,
    task: Object.fromEntries(fields.map((k) => [k, task[k] ?? null])),
    project: { id: project.id, project_path: project.project_path, core_goal: project.core_goal },
    agent: {
      id: agent.id,
      department_id: agent.department_id ?? null,
      role: agent.role ?? null,
      cli_provider: agent.cli_provider ?? null,
      cli_model: agent.cli_model ?? null,
      cli_reasoning_level: agent.cli_reasoning_level ?? null,
    },
    source,
    head,
    handoff: digest(content),
    sourceCodexConfigAbsent: true,
    runner: officeRunner(),
    providerModelConfig: modelConfigurationDigest(),
    knowledge: officeKnowledge(projectPath)?.revision ?? null,
  };
  return {
    taskId,
    projectId: project.id,
    projectPath,
    source,
    phase,
    digest: digest(snapshot),
    head,
    payload: JSON.stringify(snapshot),
  };
}
export function prepareOfficeTask(taskId: string, phase: Phase): OfficePolicy {
  if (!officePolicyEnabled()) fail("office_policy_disabled", 503);
  const result = transaction(() => {
    if (
      db().prepare("SELECT state FROM office_task_permissions WHERE task_id = ?").get(id(taskId))?.state === "running"
    )
      fail("office_task_running", 409);
    const p = current(taskId, phase),
      now = Date.now(),
      expiresAt = now + TTL;
    db()
      .prepare(
        `INSERT INTO office_task_permissions VALUES (?, ?, ?, ?, 'pending', ?, ?) ON CONFLICT(task_id) DO UPDATE SET phase=excluded.phase,digest=excluded.digest,payload=excluded.payload,state='pending',expires_at=excluded.expires_at,updated_at=excluded.updated_at`,
      )
      .run(taskId, phase, p.digest, p.payload, expiresAt, now);
    const { payload: _, ...result } = p;
    return { ...result, state: "pending", expiresAt };
  });
  if (developmentTaskGrant?.taskId === taskId) developmentTaskGrant = null;
  return result;
}
function inspect(taskId: string, states: string[]): OfficePolicy {
  const row = db().prepare("SELECT * FROM office_task_permissions WHERE task_id = ?").get(id(taskId));
  if (!row || !states.includes(row.state)) fail("office_approval_required");
  if (row.expires_at <= Date.now()) fail("office_approval_expired", 409);
  const p = current(taskId, row.phase);
  if (!same(row.digest, p.digest) || row.payload !== p.payload) fail("office_approval_stale", 409);
  const { payload: _, ...result } = p;
  return { ...result, state: row.state, expiresAt: row.expires_at };
}
export function inspectOfficeTask(taskId: string): OfficePolicy | null {
  return officePolicyEnabled() ? inspect(taskId, ["approved"]) : null;
}
export function requireOfficeWorker(taskId: string): OfficePolicy | null {
  const p = inspectOfficeTask(taskId);
  const grant = currentDevelopmentGrant();
  if (grant) {
    if (
      p?.phase !== "development" ||
      grant.taskId !== taskId ||
      !same(grant.digest, p.digest) ||
      grant.expiresAt !== p.expiresAt
    )
      fail("office_scoped_development_task_mismatch", 409);
    return p;
  }
  if (p && process.env.AI_OFFICE_WORKERS_ENABLED !== "true") fail("office_workers_disabled", 503);
  if (p?.phase === "development" && process.env.AI_OFFICE_DEVELOPMENT_ENABLED !== "true")
    fail("office_development_disabled", 503);
  return p;
}
export function approveOfficeTask(taskId: string, expectedDigest: string, confirmation: unknown): OfficePolicy {
  if (!officePolicyEnabled()) fail("office_policy_disabled", 503);
  if (confirmation !== true) fail("office_confirmation_required", 400);
  return transaction(() => {
    const p = inspect(taskId, ["pending"]);
    if (!same(expectedDigest, p.digest)) fail("office_digest_mismatch", 409);
    db()
      .prepare("UPDATE office_task_permissions SET state='approved',updated_at=? WHERE task_id=? AND state='pending'")
      .run(Date.now(), taskId);
    return { ...p, state: "approved" };
  });
}
export function revokeOfficeTask(taskId: string): void {
  if (!officePolicyEnabled()) fail("office_policy_disabled", 503);
  transaction(() => {
    const row = db().prepare("SELECT state FROM office_task_permissions WHERE task_id = ?").get(id(taskId));
    if (row?.state === "running") fail("office_task_running", 409);
    db()
      .prepare("UPDATE office_task_permissions SET state='revoked',updated_at=? WHERE task_id=?")
      .run(Date.now(), taskId);
  });
  if (developmentTaskGrant?.taskId === taskId) developmentTaskGrant = null;
}
export function claimOfficeTask(taskId: string, expectedDigest: string): OfficePolicy {
  const result = transaction(() => {
    const p = requireOfficeWorker(taskId);
    if (!p) fail("office_policy_disabled", 503);
    if (!same(expectedDigest, p.digest)) fail("office_digest_mismatch", 409);
    const result = db()
      .prepare(
        "UPDATE office_task_permissions SET state='running',updated_at=? WHERE task_id=? AND digest=? AND state='approved' AND expires_at>?",
      )
      .run(Date.now(), taskId, expectedDigest, Date.now());
    if (result.changes !== 1) fail("office_approval_already_claimed", 409);
    return { ...p, state: "running" };
  });
  if (developmentTaskGrant?.taskId === taskId) developmentTaskGrant = null;
  return result;
}
export function finishOfficeTask(taskId: string, success: boolean): void {
  if (!officePolicyEnabled()) return;
  db()
    .prepare("UPDATE office_task_permissions SET state=?,updated_at=? WHERE task_id=? AND state='running'")
    .run(success ? "consumed" : "failed", Date.now(), id(taskId));
}
export function blockOfficeUnscopedExecution(): void {
  if (officePolicyEnabled()) fail("office_unscoped_execution_blocked");
}
export function officeCliArgs(phase: Phase, model?: string, reasoning?: string): string[] {
  if (!["product", "development"].includes(phase)) fail("office_invalid_phase", 400);
  return [
    "codex",
    "--disable",
    "multi_agent",
    "--ask-for-approval",
    "never",
    "--sandbox",
    phase === "product" ? "read-only" : "workspace-write",
    "-c",
    "sandbox_workspace_write.network_access=false",
    "-c",
    "sandbox_workspace_write.exclude_tmpdir_env_var=true",
    "-c",
    "sandbox_workspace_write.exclude_slash_tmp=true",
    ...(model && model !== "provider-default" ? ["-m", model] : []),
    ...(reasoning ? ["-c", `model_reasoning_effort=${JSON.stringify(reasoning)}`] : []),
    "exec",
    "--json",
  ];
}
export function officeWorkerEnvironment(env: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
  const keys = new Set([
    "PATH",
    "HOME",
    "USER",
    "LOGNAME",
    "LANG",
    "LANGUAGE",
    "TZ",
    "TERM",
    "SHELL",
    "TMPDIR",
    "HTTP_PROXY",
    "HTTPS_PROXY",
    "ALL_PROXY",
    "NO_PROXY",
    "http_proxy",
    "https_proxy",
    "all_proxy",
    "no_proxy",
    "SSL_CERT_FILE",
    "SSL_CERT_DIR",
    "NODE_EXTRA_CA_CERTS",
    "REQUESTS_CA_BUNDLE",
    "CURL_CA_BUNDLE",
  ]);
  return Object.fromEntries(Object.entries(env).filter(([k]) => keys.has(k) || /^LC_[A-Z_]+$/.test(k)));
}
function providerHome(source?: string): string {
  const raw = process.env.AI_OFFICE_PROVIDER_AUTH_DIR;
  if (!raw) fail("office_provider_home_required", 503);
  const home = real(raw),
    root = real(process.env.AI_OFFICE_PROJECTS_ROOT || "/workspace/ai-office/projects");
  if (home === real(os.homedir()) || inside(home, root) || (source && (inside(source, home) || inside(home, source))))
    fail("office_invalid_provider_home");
  if (fs.readdirSync(home).some((n) => n !== ".codex")) fail("office_provider_home_not_fresh");
  const codex = path.join(home, ".codex");
  if (real(codex) !== codex || fs.readdirSync(codex).some((n) => n !== "auth.json"))
    fail("office_provider_home_not_fresh");
  const auth = path.join(codex, "auth.json");
  if (real(auth) !== auth || !fs.statSync(auth).isFile() || fs.statSync(auth).size > 524288)
    fail("office_invalid_provider_auth");
  return home;
}
function developmentNodeToolchain(): string | null {
  // Local installers run the server with this verified, dedicated Node. The
  // bundle contains node/npm libraries, not the adjacent private office state.
  const root = "/workspace/ai-office/toolchain/node";
  const binary = path.join(root, "bin", "node");
  if (process.execPath !== binary) return null;
  if (real(root) !== root || real(binary) !== binary || !fs.statSync(binary).isFile())
    fail("office_node_toolchain_path_requires_review");
  return root;
}
export function officeSandboxCommand(
  taskId: string,
  provider: string,
  cwd: string,
  model?: string,
  reasoning?: string,
): { args: string[]; policy: OfficePolicy } {
  const policy = requireOfficeWorker(taskId);
  if (!policy) fail("office_policy_disabled", 503);
  if (provider !== "codex") fail("office_provider_not_supported");
  const working = real(cwd);
  if (policy.phase === "product" && working !== policy.source) fail("office_product_cwd_mismatch");
  if (policy.phase === "development") {
    const parent = path.join(policy.source, ".climpire-worktrees"),
      prefix = id(taskId).slice(0, 8),
      name = path.basename(working);
    if (path.dirname(working) !== parent || ![prefix, prefix + "-1", prefix + "-2", prefix + "-3"].includes(name))
      fail("office_development_cwd_mismatch");
    if (
      git(working, "rev-parse", "HEAD") !== policy.head ||
      real(git(working, "rev-parse", "--absolute-git-dir")) !== path.join(policy.source, ".git", "worktrees", name)
    )
      fail("office_worktree_head_mismatch");
  }
  for (let ancestor = working; inside(ancestor, policy.source); ancestor = path.dirname(ancestor)) {
    denyProjectConfiguration(ancestor);
    if (ancestor === policy.source) break;
  }
  const targetHome = real(os.homedir());
  if (inside(policy.source, targetHome) || inside(targetHome, policy.source)) fail("office_home_project_overlap");
  const runner = officeRunner();
  const authHome = validateChatGptAuth(policy.source);
  probeOfficeSandbox();
  const args = ["bwrap", "--die-with-parent", "--new-session", "--unshare-pid", "--unshare-ipc", "--unshare-uts"];
  for (const mount of ["/usr", "/bin", "/sbin", "/lib", "/lib64", "/opt", "/etc/ssl", "/etc/hosts", "/etc/resolv.conf"])
    if (fs.existsSync(mount)) args.push("--ro-bind", mount, mount);
  args.push(
    "--proc",
    "/proc",
    "--dev",
    "/dev",
    "--tmpfs",
    "/tmp",
    "--tmpfs",
    targetHome,
    "--dir",
    path.join(targetHome, ".codex"),
    "--ro-bind",
    path.join(authHome, ".codex", "auth.json"),
    path.join(targetHome, ".codex", "auth.json"),
    "--ro-bind",
    policy.source,
    policy.source,
  );
  if (policy.phase === "development") {
    const nodeToolchain = developmentNodeToolchain();
    if (nodeToolchain) args.push("--ro-bind", nodeToolchain, nodeToolchain);
    args.push("--bind", working, working);
  }
  const knowledge = officeKnowledge(policy.projectPath);
  if (knowledge) args.push("--ro-bind", knowledge.directory, "/run/office-knowledge");
  args.push("--ro-bind", runner.bundle, "/run/office-provider");
  args.push(
    "--chdir",
    working,
    "/run/office-provider/bin/codex",
    ...officeCliArgs(policy.phase, model, reasoning).slice(1),
  );
  return { args, policy };
}
export function installOfficePolicyRoutes(app: any, input: any): void {
  configureOfficePolicy(input);
  const wrap = (fn: (req: any, res: any) => void) => (req: any, res: any) => {
    try {
      fn(req, res);
    } catch (e: any) {
      res.status(e.status || 500).json({ error: e.code || "office_policy_error" });
    }
  };
  const owner = (req: any) => {
    const key = process.env.AI_OFFICE_OWNER_KEY;
    if (!key || !same(req.headers["x-office-owner-key"], key)) fail("office_owner_confirmation_required");
  };
  app.use((req: any, res: any, next: any) => {
    if (!officePolicyEnabled() || ["GET", "HEAD", "OPTIONS"].includes(req.method)) return next();
    const p = req.path.replace(/\/+$/, "");
    if (
      [
        "/api/inbox",
        "/api/messages",
        "/api/github/clone",
        "/api/skills/learn",
        "/api/skills/unlearn",
        "/api/update-apply",
        "/api/update-auto-config",
      ].includes(p) ||
      /\/merge$/.test(p) ||
      /^\/api\/agents\/[^/]+\/spawn$/.test(p)
    )
      return res.status(403).json({ error: "office_unscoped_execution_blocked" });
    const run = /^\/api\/tasks\/([^/]+)\/run$/.exec(p);
    if (run) {
      try {
        requireOfficeWorker(run[1]);
      } catch (e: any) {
        return res.status(e.status || 403).json({ error: e.code || "office_policy_error" });
      }
    }
    next();
  });
  app.get(
    "/api/office-policy/status",
    wrap((_req, res) =>
      res.json({
        enabled: officePolicyEnabled(),
        workersEnabled: process.env.AI_OFFICE_WORKERS_ENABLED === "true",
