describe("one-task development admission without global unlock", () => {
  beforeEach(() => {
    vi.stubEnv("AI_OFFICE_DEVELOPMENT_ENABLED", "false");
    database.exec("ALTER TABLE tasks ADD COLUMN status TEXT DEFAULT 'inbox'");
    vi.mocked(spawnSync).mockReturnValue({ status: 0 } as any);
  });

  function otherTask(phase: "product" | "development") {
    const other = "87654321-other-task";
    database
      .prepare(
        "INSERT INTO tasks SELECT ?,title,description,task_type,assigned_agent_id,project_id,project_path,department_id,workflow_pack_key,base_branch,status FROM tasks WHERE id=?",
      )
      .run(other, taskId);
    const policy = prepareOfficeTask(other, phase);
    approveOfficeTask(other, policy.digest, true);
    return other;
  }

  it("requires owner authentication, exact approved development scope and explicit confirmation", async () => {
    const a = app(),
      url = `/api/office-policy/tasks/${taskId}/development-unlock`;
    let policy = approve();
    await request(a)
      .post(url)
      .set("x-standard-auth", "fixture")
      .send({ expectedDigest: policy.digest, confirmation: true })
      .expect(403);
    code(() => unlockOfficeDevelopmentTask(taskId, policy.digest, true), "office_development_approval_required");
    policy = approve("development");
    code(() => unlockOfficeDevelopmentTask(taskId, policy.digest, false), "office_confirmation_required");
    code(() => unlockOfficeDevelopmentTask(taskId, "0".repeat(64), true), "office_digest_mismatch");
    const result = await request(a)
      .post(url)
      .set("x-standard-auth", "fixture")
      .set("x-office-owner-key", "fixture-owner-key")
      .send({ expectedDigest: policy.digest, confirmation: true })
      .expect(200);
    expect(result.body).toEqual({
      taskId,
      phase: "development",
      scoped: true,
      workersEnabled: false,
      developmentEnabled: false,
      expiresAt: policy.expiresAt,
    });
    expect(process.env.AI_OFFICE_WORKERS_ENABLED).toBe("false");
    expect(process.env.AI_OFFICE_DEVELOPMENT_ENABLED).toBe("false");
    expect(requireOfficeWorker(taskId)?.phase).toBe("development");
  });

  it.each(["product", "development"] as const)(
    "blocks another already approved %s task while the scoped grant is armed",
    (phase) => {
      const other = otherTask(phase),
        policy = approve("development");
      unlockOfficeDevelopmentTask(taskId, policy.digest, true);
      code(() => requireOfficeWorker(other), "office_scoped_development_task_mismatch");
      code(() => unlockOfficeProductWorkers(true), "office_scoped_development_pending");
      code(() => unlockOfficeDevelopmentTask(taskId, policy.digest, true), "office_scoped_development_pending");
      expect(requireOfficeWorker(taskId)?.taskId).toBe(taskId);
    },
  );

  it("consumes admission exactly once and leaves global switches locked", () => {
    const policy = approve("development");
    unlockOfficeDevelopmentTask(taskId, policy.digest, true);
    expect(claimOfficeTask(taskId, policy.digest).state).toBe("running");
    code(() => claimOfficeTask(taskId, policy.digest), "office_approval_required");
    finishOfficeTask(taskId, false);
    const fresh = approve("development");
    code(() => requireOfficeWorker(taskId), "office_workers_disabled");
    expect(fresh.digest).toBe(policy.digest);
    expect(process.env.AI_OFFICE_WORKERS_ENABLED).toBe("false");
  });

  it("clears admission on explicit lock, reprepare, revoke and policy reinitialization", () => {
    for (const [clear, reason] of [
      [() => lockOfficeWorkers(), "office_workers_disabled"],
      [() => prepare("development"), "office_approval_required"],
      [() => revokeOfficeTask(taskId), "office_approval_required"],
      [() => configureOfficePolicy(database), "office_workers_disabled"],
    ] as const) {
      const policy = approve("development");
      unlockOfficeDevelopmentTask(taskId, policy.digest, true);
      clear();
      code(() => requireOfficeWorker(taskId), reason);
    }
  });

  it("rejects stale scope and expired permission before admission", () => {
    let policy = approve("development");
    database.exec("UPDATE tasks SET description='changed'");
    code(() => unlockOfficeDevelopmentTask(taskId, policy.digest, true), "office_approval_stale");
    policy = approve("development");
    database.exec("UPDATE office_task_permissions SET expires_at=0");
    code(() => unlockOfficeDevelopmentTask(taskId, policy.digest, true), "office_approval_expired");
    expect(process.env.AI_OFFICE_WORKERS_ENABLED).toBe("false");
  });

  it("requires idle runtime and successful sandbox before admission", () => {
    const policy = approve("development");
    database.exec("UPDATE tasks SET status='in_progress'");
    code(() => unlockOfficeDevelopmentTask(taskId, policy.digest, true), "office_wait_for_running_task");
    database.exec("UPDATE tasks SET status='inbox'");
    database.exec("UPDATE office_task_permissions SET state='running'");
    code(() => unlockOfficeDevelopmentTask(taskId, policy.digest, true), "office_wait_for_running_task");
    database.exec("UPDATE office_task_permissions SET state='approved'");
    vi.mocked(spawnSync).mockReturnValue({ status: 1 } as any);
    code(() => unlockOfficeDevelopmentTask(taskId, policy.digest, true), "office_os_sandbox_unavailable");
    code(() => requireOfficeWorker(taskId), "office_workers_disabled");
    vi.stubEnv("AI_OFFICE_WORKERS_ENABLED", "true");
    code(() => unlockOfficeDevelopmentTask(taskId, policy.digest, true), "office_global_workers_must_remain_locked");
  });

  it("expires its in-memory capability without opening global workers", () => {
    const policy = approve("development");
    unlockOfficeDevelopmentTask(taskId, policy.digest, true);
    const clock = vi.spyOn(Date, "now").mockReturnValue(policy.expiresAt + 1);
    try {
      code(() => requireOfficeWorker(taskId), "office_approval_expired");
      // A product unlock can no longer see an active scoped grant after expiry.
      expect(unlockOfficeProductWorkers(true).workersEnabled).toBe(true);
      lockOfficeWorkers();
    } finally {
      clock.mockRestore();
    }
  });
});

